<script setup>
import {ref,watch,nextTick} from 'vue';
import {TOKENS} from '../../attestations/model';
const blocks=defineModel({type:Array,required:true});
const props=defineProps({disabled:Boolean,logo:String});
const active=ref(0),inserting=ref(false),areas=ref([]);
const labels=Object.fromEntries(TOKENS);
function chip(key){const el=document.createElement('span');el.dataset.token=key;el.contentEditable='false';el.className='auto-value';el.textContent=labels[key]||key;el.title='Information automatique';return el;}
function render(){blocks.value.forEach((block,index)=>{const area=areas.value[index];if(!area)return;const fragment=document.createDocumentFragment();let offset=0;for(const m of block.text.matchAll(/{{\s*([^{}]+?)\s*}}/g)){fragment.append(document.createTextNode(block.text.slice(offset,m.index)),chip(m[1]));offset=m.index+m[0].length;}fragment.append(document.createTextNode(block.text.slice(offset)));area.replaceChildren(fragment);});}
watch(()=>blocks.value,()=>{active.value=Math.min(active.value,blocks.value.length-1);nextTick(render);},{immediate:true});
function read(node){if(node.nodeType===3)return node.textContent;if(node.dataset?.token)return '{{'+node.dataset.token+'}}';if(node.nodeName==='BR')return '\n';return Array.from(node.childNodes).map(read).join('')+(['DIV','P'].includes(node.nodeName)&&node.nextSibling?'\n':'');}
function sync(index){blocks.value[index].text=Array.from(areas.value[index].childNodes).map(read).join('');}
function addAtCursor(node){const area=areas.value[active.value],selection=window.getSelection();let range;if(selection?.rangeCount&&area.contains(selection.anchorNode)){range=selection.getRangeAt(0);range.deleteContents();}else{range=document.createRange();range.selectNodeContents(area);range.collapse(false);}range.insertNode(node);range.setStartAfter(node);range.collapse(true);selection?.removeAllRanges();selection?.addRange(range);area.focus();sync(active.value);}
function insert(key){addAtCursor(chip(key));inserting.value=false;}
function paste(event,index){active.value=index;event.preventDefault();addAtCursor(document.createTextNode(event.clipboardData.getData('text/plain')));}
function enter(event,index){if(event.key==='Enter'){active.value=index;event.preventDefault();addAtCursor(document.createTextNode('\n'));}}
function add(){blocks.value=[...blocks.value.slice(0,active.value+1),{text:'Votre texte',align:'left',size:11,gap:16},...blocks.value.slice(active.value+1)];active.value++;}
function remove(){if(blocks.value.length===1)return;blocks.value=blocks.value.filter((_,i)=>i!==active.value);}
function move(delta){const next=active.value+delta;if(next<0||next>=blocks.value.length)return;const copy=[...blocks.value];[copy[active.value],copy[next]]=[copy[next],copy[active.value]];active.value=next;blocks.value=copy;}
</script>
<template><div class="canvas">
 <div v-if="!disabled&&blocks[active]" class="toolbar"><strong>Bloc {{active+1}}</strong><select v-model="blocks[active].align" aria-label="Alignement du bloc"><option value="left">À gauche</option><option value="center">Centré</option><option value="right">À droite</option><option value="justify">Justifié</option></select><select v-model.number="blocks[active].size" aria-label="Taille du texte"><option v-for="size in [10,11,12,14,16,18,20,24]" :key="size" :value="size">{{size}} pt</option></select><button class="tool" :aria-pressed="!!blocks[active].bold" @mousedown.prevent @click="blocks[active].bold=!blocks[active].bold"><b>Gras</b></button><button class="tool" :aria-pressed="!!blocks[active].shade" @mousedown.prevent @click="blocks[active].shade=!blocks[active].shade">Fond gris</button><label>Espace après <select v-model.number="blocks[active].gap" aria-label="Espace après le bloc"><option v-for="gap in [0,8,12,16,24,32,42,56,72,100]" :key="gap" :value="gap">{{gap}} pt</option></select></label><button class="tool" @mousedown.prevent @click="inserting=!inserting">+ Information automatique</button><button class="tool" @click="add" :disabled="blocks.length>=40">+ Bloc texte</button><button class="tool" aria-label="Monter le bloc" :disabled="active===0" @click="move(-1)">↑</button><button class="tool" aria-label="Descendre le bloc" :disabled="active===blocks.length-1" @click="move(1)">↓</button><button class="tool" :disabled="blocks.length===1" @click="remove">Supprimer le bloc</button></div>
 <div v-if="inserting" class="token-list"><button v-for="[key,label] in TOKENS" :key="key" class="tool" @mousedown.prevent @click="insert(key)">{{label}}</button></div>
 <p class="help">Cliquez dans une zone pour modifier son texte et sa présentation. Toute la feuille est modifiable. Les encadrés bleus sont remplis automatiquement.</p>
 <article class="document-sheet"><img v-if="logo" :src="logo" alt="Logo de la société" class="document-logo"/><div v-for="(block,index) in blocks" :key="index" class="block" :class="{selected:active===index&&!disabled}" :style="{marginBottom:block.gap+'pt',textAlign:block.align,fontSize:block.size+'pt',fontWeight:block.bold?'700':'400',background:block.shade?'#bdbdbd':'transparent',borderColor:block.shade?'#333':undefined}"><div :ref="el=>areas[index]=el" :contenteditable="disabled?'false':'true'" role="textbox" aria-multiline="true" :aria-label="'Bloc '+(index+1)+' du document'" class="editable" @focus="active=index" @input="sync(index)" @paste="paste($event,index)" @keydown="enter($event,index)" @drop.prevent></div></div></article>
</div></template>
<style scoped>
.toolbar{position:sticky;top:110px;z-index:3;display:flex;align-items:center;flex-wrap:wrap;gap:6px;padding:10px;background:#f5f8fc;border:1px solid #d5e0ed;border-radius:8px;box-shadow:0 2px 6px #14345d0b;font-size:12px}.toolbar select{width:auto;padding:4px 6px;min-height:29px;font-size:12px}.toolbar label{display:flex;align-items:center;gap:4px}.tool{background:white;border:1px solid #cedaea;border-radius:5px;color:#244e85;padding:5px 9px;cursor:pointer;font-size:12px}.tool[aria-pressed=true]{background:#dceaff;border-color:#4f81c7}.tool:disabled{opacity:.4;cursor:default}.token-list{display:flex;flex-wrap:wrap;gap:5px;padding:12px;background:#edf5ff}.help{font-size:12px;color:#62738b}.document-sheet{box-sizing:border-box;width:100%;max-width:794px;min-height:1000px;margin:14px auto;padding:38px 32px 80px;background:white;border:1px solid #d8e1eb;box-shadow:0 3px 14px #17375d0d;color:#111;font-family:Arial,sans-serif;line-height:1.45}.document-logo{display:block;max-width:130px;max-height:70px;margin:0 0 20px auto}.block{border:1px solid transparent;min-height:22px;position:relative}.block.selected,.block:hover{outline:1px dashed #9bbbe0;outline-offset:3px}.editable{white-space:pre-wrap;overflow-wrap:anywhere;outline:0;min-height:1.4em}.editable :deep(.auto-value){background:#edf5ff;color:#1e5da8;border:1px solid #cbdff5;border-radius:3px;padding:0 2px;font-size:.88em;box-decoration-break:clone;font-weight:400}@media(max-width:600px){.document-sheet{padding:25px 18px}.toolbar{position:static}}
</style>
